CREATE TABLE "invoices" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "client_id" TEXT NOT NULL, "invoice_number" TEXT NOT NULL, "title" TEXT NOT NULL, "invoice_status" TEXT NOT NULL DEFAULT 'draft', "issue_date" TIMESTAMP(3), "due_date" TIMESTAMP(3), "notes" TEXT, "created_by" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "invoices_pkey" PRIMARY KEY ("id"));
CREATE TABLE "invoice_items" ("id" TEXT NOT NULL, "invoice_id" TEXT NOT NULL, "description" TEXT NOT NULL, "quantity" DOUBLE PRECISION NOT NULL DEFAULT 1, "unit_price" DOUBLE PRECISION NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "invoice_items_pkey" PRIMARY KEY ("id"));
CREATE TABLE "payments" ("id" TEXT NOT NULL, "invoice_id" TEXT NOT NULL, "amount" DOUBLE PRECISION NOT NULL, "paid_at" TIMESTAMP(3) NOT NULL, "method" TEXT, "reference" TEXT, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "payments_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "invoices_company_id_invoice_number_key" ON "invoices"("company_id", "invoice_number"); CREATE INDEX "invoices_company_id_idx" ON "invoices"("company_id"); CREATE INDEX "invoice_items_invoice_id_idx" ON "invoice_items"("invoice_id"); CREATE INDEX "payments_invoice_id_idx" ON "payments"("invoice_id");
ALTER TABLE "invoices" ADD CONSTRAINT "invoices_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "invoices" ADD CONSTRAINT "invoices_client_id_fkey" FOREIGN KEY ("client_id") REFERENCES "clients"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "invoice_items" ADD CONSTRAINT "invoice_items_invoice_id_fkey" FOREIGN KEY ("invoice_id") REFERENCES "invoices"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "payments" ADD CONSTRAINT "payments_invoice_id_fkey" FOREIGN KEY ("invoice_id") REFERENCES "invoices"("id") ON DELETE CASCADE ON UPDATE CASCADE;
